#!/usr/bin/env python3
import base64,gzip,pathlib
ROOT=pathlib.Path(__file__).resolve().parent
(ROOT/"events_2021_2026.csv").write_bytes(gzip.decompress(base64.b64decode("")))
code=gzip.decompress(base64.b64decode(""))
g={"__name__":"__main__","__file__":str(__file__)}
exec(compile(code,str(__file__),"exec"),g,g)
